package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.mockito.Mockito;
import java.util.Optional;

public class PropertyListBuilderTest {

    @Test
    public void addPropertyTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        List<Property<?>> properties = new ArrayList<>();
        builder.add(properties.get(0));
        assertEquals(1, builder.getRootEntries().size());
    }

    @Test
    public void createPropertiesTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        List<Property<?>> properties = new ArrayList<>();
        builder.add(properties.get(0));
        List<Property<?>> result = builder.create();
        assertTrue(result.contains(properties.get(0)));
    }

    @Test
    public void getRootEntriesTest() {
        PropertyListBuilder builder = new PropertyListBuilder();
        Map<String, Object> entries = new LinkedHashMap<>();
        builder.getRootEntries().put("entry1", "value1");
        assertEquals(1, builder.getRootEntries().size());
    }

    @Test
    public void addEmptyPropertyTest() throws ConfigMeException {
        PropertyListBuilder builder = new PropertyListBuilder();
        Optional<Property<?>> property = Optional.empty();
        try {
            builder.add(property.get());
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {}

        Optional<Property<?>> emptyProperty = Optional.of(new Property<>());
        builder.add(emptyProperty.get());
    }

    @Test
    public void createEmptyPropertiesTest() throws ConfigMeException {
        PropertyListBuilder builder = new PropertyListBuilder();
        List<Optional<Property?>> properties = new ArrayList<>();
        try {
            builder.create(properties.get(0));
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {}

        List<Optional<Property ?>> emptyProperties = new ArrayList<>();
        builder.create(emptyProperties);
    }

    @Test
    public void addNullPropertyTest() throws ConfigMeException {
        PropertyListBuilder builder = new PropertyListBuilder();
        Optional<Property<?>> property = Mockito.mock(Property.class);
        Mockito.when(property.get()).thenReturn(null);
        try {
            builder.add(property.get());
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {}

        Optional<Property?> nullProperty = Optional.empty();
        builder.add(nullProperty.get());
    }

}
